import * as C from './core.js';
import * as DB from './storage.js';
import {askLogin} from './auth.js';
import {measureUnits,displayMeasure,canonicalMeasure,rulerTicks} from './measurements.js';
let account=null;
import {switcher, installLanguageSwitcher} from './i18n.js';
installLanguageSwitcher();
const app=document.querySelector('#app');
let state, route='dashboard', selectedDate, selectedWeek, dailyDraft, savedDraft, reflectionDraft='', reflectionSaved='', profileSaved='', loadError='', busy=false, toastTimer, undoTimer, undoEntry=null, lastDay;
const expandedHelp=new Set();
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 10h18m-14 4h2m4 0h2m-8 3h2',chart:'M4 20V10h3v10m4 0V4h3v16m4 0v-7h3v7',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Zm3 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8',arrow:'M5 12h14m-6-6 6 6-6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6Zm3 0V6a3 3 0 0 1 6 0v4m-3 4v3',info:'M12 10v7m0-11v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chevron:'m6 9 6 6 6-6',left:'m15 5-7 7 7 7',right:'m9 5 7 7-7 7',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-4 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0m-5 0h.01',leaf:'M20 3C8 1 1 8 5 16s17 1 15-13ZM5 21l10-12',protein:'M8 8c-6-4-9 4-4 6 0 5 8 6 9 1l5-5c5 0 6-7 1-8-2-4-8 0-6 4Z',walk:'M15 4h.01m-3 4 3 2 3 1m-6-3-2 6-4 6m4-6 5 2 2 5M12 8l-4 3H5',strength:'M3 8v8m3-10v12m0-6h12m0-6v12m3-10v8',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',edit:'m15 4 5 5-11 11H4v-5Zm-2 2 5 5',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',flag:'M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0',x:'m6 6 12 12M6 18 18 6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z'};
const icon=(n,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${n==='settings'?'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-7 9a7 7 0 0 1 14 0Z':paths[n]||paths.info}"/></svg>`;
const btn=(label,action,kind='',extra='')=>`<button type="button" class="btn ${kind}" data-act="${action}" ${extra}>${label}</button>`;
const badge=(label,kind='',ico='')=>`<span class="badge ${kind}">${ico?icon(ico):''}${label}</span>`;
const bar=p=>`<div class="bar" ${p===null?'':`role="progressbar" aria-label="Progress" aria-valuenow="${Math.round(p*100)}" aria-valuemin="0" aria-valuemax="100"`}><span style="width:${p===null?0:Math.min(100,p*100)}%"></span></div>`;
const brand=()=>`<div class="brand"><div class="brand-mark">${icon('flag')}</div><span>epic<small>Diet tracker</small></span></div>`;
const today=()=>C.todayIn(state?.profile?.timeZone);
const tabs=[['dashboard','Dashboard','home'],['daily','Catatan Harian','calendar'],['weekly','Mingguan','chart'],['roadmap','Roadmap','map']];
function nav(){return tabs.map(([id,label,i])=>`<a class="nav-link ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''} data-route="${id}">${icon(i)}<span>${label}</span></a>`).join('');}
function pageHead(title,description,cta=''){if(title==='Pengaturan'){title='Profil';description='';cta=btn(`Dashboard ${icon('right')}`,'dashboard','profile-dashboard');}const journey=route==='dashboard'&&state?.profile?`<section class="card journey-dashboard"><div class="card-head"><div><span class="eyebrow">Posisi kamu sekarang</span><h2>${C.fmt(currentJourneyWeight())} kg</h2></div>${badge('Berat terbaru','green')}</div>${journeyVisual(currentJourneyWeight())}</section>`:'';return `<div class="page-head"><div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${cta}</div>${journey}`;}
function shell(body){return `<aside class="sidebar">${brand()}<nav aria-label="Navigasi utama">${nav()}</nav><div class="sidebar-foot"><div class="habit-title">${icon('shield')} Ruang pribadi kamu</div><p class="muted small">Satu hari yang tidak sempurna tetap bagian dari perjalanan.</p><span class="small muted">Akun pribadi</span></div></aside><div class="layout"><header class="topbar"><div class="topbar-label muted small">Perjalanan / <span style="color:var(--ink)">${tabs.find(t=>t[0]===route)?.[1]||'Pengaturan'}</span></div>${brand()}<div class="topbar-right"><span class="small muted">${C.formatDate(today(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span><button type="button" class="icon-btn" data-act="settings" aria-label="Pengaturan">${icon('settings')}</button><span class="avatar">R</span>${switcher()}</div></header><main id="main" class="container">${body}</main><nav class="bottom-nav" aria-label="Navigasi mobile">${nav()}</nav></div>`;}
function inputField(label,name,value,{unit='',help='',type='text',optional=false,attrs=''}={}){return `<div class="field"><label for="${name}">${label}${optional?'<span class="optional">Opsional</span>':''}</label><div class="input-wrap"><input class="input" id="${name}" name="${name}" type="${type}" ${type==='text'?'inputmode="decimal"':''} value="${esc(value)}" aria-describedby="${name}-help ${name}-error" ${attrs}>${unit?`<span class="unit">${unit}</span>`:''}</div><p id="${name}-help">${help}</p><p class="error" id="${name}-error"></p></div>`;}
const JOURNEY_WEIGHTS=[82,75,70,65,60];
function journeyIndex(value){const n=C.parseNumber(value);if(!Number.isFinite(n))return 0;return JOURNEY_WEIGHTS.reduce((best,kg,i)=>Math.abs(n-kg)<Math.abs(n-JOURNEY_WEIGHTS[best])?i:best,0);}
function journeyVisual(value){const current=journeyIndex(value),next=current<4?current+1:null,currentKg=JOURNEY_WEIGHTS[current];return `<div class="journey-viz"><div class="journey-chart" role="img" aria-label="Posisi kamu saat ini paling dekat dengan ${currentKg} kg. ${next===null?'Goal 60 kg tercapai.':`Target berikutnya ${JOURNEY_WEIGHTS[next]} kg.`}"><div class="journey-figures stage-${current}" aria-hidden="true"><img class="figures-muted" src="/journey-women.png" alt=""><img class="figure-color" src="/journey-women.png" alt=""></div><div class="journey-scale">${JOURNEY_WEIGHTS.map((kg,i)=>`<span class="${i===current?'current':''}">${kg} kg</span>`).join('')}</div><div class="journey-track" aria-hidden="true">${JOURNEY_WEIGHTS.map((_,i)=>`<span class="journey-marker ${i===current?'current':i===next?'next':'future'}"></span>`).join('')}</div><div class="journey-captions" aria-hidden="true">${JOURNEY_WEIGHTS.map((_,i)=>i===current?'<strong>Posisi kamu</strong>':i===next?'<strong>Target berikutnya</strong>':'<span></span>').join('')}</div></div></div>`;}
function currentJourneyWeight(){const latest=Object.values(state.entries).filter(e=>e.localDate<=today()&&Number.isFinite(e.weightKg)).sort((a,b)=>b.localDate.localeCompare(a.localDate))[0];return latest?.weightKg??state.profile.baselineKg;}
function onboarding(){
  const d=today();
  const measure=(name,label,value,unit,min,max,step)=>`<div class="health-measure" data-measure-card="${name}" data-unit="${unit}"><div class="health-measure-head"><label for="${name}-display">${label}</label><div class="measure-units" role="group" aria-label="${label}">${(name==='baselineKg'?[['kg','Kg'],['lb','Pound']]:[['ft','Feet'],['cm','Cm']]).map(([u,l])=>`<button type="button" data-unit-choice="${u}" data-unit-field="${name}" aria-pressed="${u===unit}" translate="no">${l}</button>`).join('')}</div></div><input type="hidden" id="${name}" name="${name}" value="${value}"><div class="health-measure-value"><input id="${name}-display" data-measure-display="${name}" inputmode="decimal" value="${value}" aria-describedby="${name}-error"><span data-measure-unit translate="no">${unit}</span></div><div class="health-ruler"><div class="health-ticks" aria-hidden="true">${rulerMarkup(value,name,unit)}</div><span class="health-marker" aria-hidden="true"></span><input type="range" data-measure="${name}" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${value}"></div><p class="error" id="${name}-error" role="alert"></p></div>`;
  return `<main id="main" class="onboarding wizard health-onboarding"><header class="health-toolbar"><button class="health-back" type="button" data-wizard-back aria-label="Langkah sebelumnya">${icon('arrow')}</button><div class="health-toolbar-right"><details class="health-menu"><summary aria-label="Bahasa"><span aria-hidden="true">•••</span></summary><div class="health-menu-content">${switcher()}</div></details><span class="health-toolbar-divider"></span><button type="button" data-act="logout" aria-label="Keluar">${icon('x')}</button></div></header>
  <form id="onboard-form" novalidate data-step="0">
    <div class="wizard-progress" aria-label="Progres profil awal"><span aria-current="step"></span><span></span></div>
    <div id="form-error" class="error-banner" role="alert">${esc(loadError)}</div>
    <section class="wizard-step basic-details" data-step-panel="0"><h1 tabindex="-1">Informasi dasar kesehatanmu</h1><p class="wizard-hint">Masukkan data yang paling akurat untukmu.</p><div class="health-measures">${measure('baselineKg','Berat',82,'kg',40,200,.1)}${measure('heightCm','Tinggi',156,'cm',100,230,1)}</div></section>
    <section class="wizard-step" data-step-panel="1" hidden><p class="wizard-kicker">02 / 02</p><h1 tabindex="-1">Apa targetmu?</h1><p class="wizard-hint">Pilih tujuan, lalu mulai dengan langkah kecil.</p>
      <fieldset class="goal-options"><legend>Target jangka panjang</legend>
      <label><input type="radio" name="longTermGoalKg" value="65"><span><strong>65 kg</strong><small>Selesai di Epic 3</small></span>${icon('check')}</label>
      <label><input type="radio" name="longTermGoalKg" value="60" checked><span><strong>60 kg</strong><small>Evaluasi ulang di 65 kg</small></span>${icon('check')}</label></fieldset><p class="error" id="longTermGoalKg-error"></p>
      ${inputField('Tanggal mulai','startDate',d,{type:'date',attrs:`max="${C.addDays(d,1)}" required`})}
      <details class="wizard-habits"><summary>Target kebiasaan harian ${icon('chevron')}</summary><div class="form-grid">${inputField('Protein / hari','proteinG',90,{unit:'g'})}${inputField('Gerak / hari','movementMinutes',30,{unit:'mnt'})}</div>${inputField('Latihan kekuatan / minggu','strengthSessions',3,{unit:'sesi'})}<p class="small muted">Target pribadi, bisa diubah di Profil.</p></details>
    </section>
    <footer class="wizard-actions"><button type="submit" class="btn primary wizard-next">Lanjut</button></footer>
  </form></main>`;
}
function showWizardStep(step){
  const form=document.querySelector('#onboard-form');form.dataset.step=step;
  form.querySelectorAll('[data-step-panel]').forEach((panel,i)=>panel.hidden=i!==step);
  form.querySelectorAll('.wizard-progress span').forEach((el,i)=>{el.classList.toggle('done',i<step);if(i===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
  form.querySelector('.wizard-next').textContent=step===1?'Simpan & buka Dashboard':'Lanjut';
  form.querySelector(`[data-step-panel="${step}"] h1`).focus();window.scrollTo(0,0);
}
function rulerMarkup(value,name,unit){return rulerTicks(value,name,unit).map(t=>`<span class="health-tick ${t.major?'major':''}" style="left:${t.position}%">${t.major?`<small>${t.label}</small>`:''}</span>`).join('');}
function syncMeasure(name,updateDisplay=true){const card=document.querySelector(`[data-measure-card="${name}"]`);if(!card)return;const value=document.getElementById(name).value,unit=card.dataset.unit;card.querySelector('[data-measure-unit]').textContent=measureUnits[name][unit].label;card.querySelector('[data-measure]').value=value;card.querySelector('.health-ticks').innerHTML=rulerMarkup(value,name,unit);if(updateDisplay)card.querySelector('[data-measure-display]').value=String(displayMeasure(value,name,unit)).replace('.',',');}
document.addEventListener('click',event=>{
  if(event.target.closest('[data-wizard-back]')){const step=Number(document.querySelector('#onboard-form').dataset.step);if(step>0)showWizardStep(step-1);else document.querySelector('.health-toolbar [data-act="logout"]').click();}
  const button=event.target.closest('[data-unit-choice]');if(button){const card=button.closest('[data-measure-card]');card.dataset.unit=button.dataset.unitChoice;card.querySelectorAll('[data-unit-choice]').forEach(b=>b.setAttribute('aria-pressed',b===button));syncMeasure(button.dataset.unitField);}
});
// Numeric fields accept digits and one comma only; a typed period becomes a comma (physical keyboards ignore inputmode).
document.addEventListener('input',event=>{
  const el=event.target;if(!(el instanceof HTMLInputElement)||el.getAttribute('inputmode')!=='decimal')return;
  const raw=el.value,caret=el.selectionStart??raw.length;let seen=false,clean='',removedBefore=0;
  for(let i=0;i<raw.length;i++){const ch=raw[i];const sep=ch==='.'||ch===',';const keep=/\d/.test(ch)||(sep&&!seen&&(seen=true));if(keep)clean+=sep?',':ch;else if(i<caret)removedBefore++;}
  if(clean!==raw){el.value=clean;const pos=caret-removedBefore;try{el.setSelectionRange(pos,pos);}catch{}}
},true);
document.addEventListener('input',event=>{
  const name=event.target.dataset.measure;
  if(name){document.getElementById(name).value=event.target.value;syncMeasure(name);}
  else if(event.target.dataset.measureDisplay){const field=event.target.dataset.measureDisplay,card=event.target.closest('[data-measure-card]'),raw=event.target.value;document.getElementById(field).value=raw.trim()===''?'':canonicalMeasure(raw,field,card.dataset.unit);syncMeasure(field,false);}
  else if(['baselineKg','heightCm'].includes(event.target.id)){const slider=document.querySelector(`[data-measure="${event.target.id}"]`);if(slider)slider.value=C.parseNumber(event.target.value);}
});
document.addEventListener('submit',event=>{
  if(event.target.id!=='onboard-form')return;
  const form=event.target,step=Number(form.dataset.step),raw=Object.fromEntries(new FormData(form)),errors=C.validateProfile(raw,today());
  const names=step===0?['baselineKg','heightCm']:Object.keys(errors);
  const relevant=Object.fromEntries(Object.entries(errors).filter(([name])=>names.includes(name)));
  if(step<1||Object.keys(relevant).length){event.preventDefault();event.stopImmediatePropagation();setErrors(relevant);
    if(Object.keys(relevant).length){if(step===1){const field=form.querySelector(`[name="${Object.keys(relevant)[0]}"]`);if(field?.closest('details'))field.closest('details').open=true;field?.focus();}}
    else showWizardStep(step+1);
  }
},true);
function weightCard(w){return `<section class="card"><div class="card-head"><h2>Rata-rata mingguan</h2>${badge(w?.ongoing?'Sementara':w?'Minggu selesai':'Mulai di sini',w?'':'green',w?'clock':'leaf')}</div>${w?`<div class="metric">${C.fmt(w.average)} <span>kg</span></div><p class="muted small">${C.period(w.start)} · ${w.weights.length} catatan timbang</p>${w.start!==C.weekStart(today())?'<p class="small muted spacer-top">Data minggu sebelumnya. Minggu ini belum cukup catatan.</p>':''}${chart(w,true)}`:`<div class="metric empty">Belum cukup data</div><p class="muted small">Rata-rata muncul setelah minimal 3 catatan timbang dalam satu minggu.</p><div class="empty-box">${icon('chart')}<br>Setiap catatan membantu<br>melihat pola dengan lebih jelas.</div>`}</section>`;}
function focusCard(j){const e=j.active;return `<section class="card dark"><div class="card-head"><span class="eyebrow">Fokus saat ini</span>${badge(j.finished?'Selesai':j.awaitingChoice?'Waktunya evaluasi':`Epic ${e?.n||'3'}`, '',j.finished?'check':'flag')}</div><h2 style="font-size:28px;margin-top:15px">${j.finished?'Target tercapai':j.awaitingChoice?'Pilih langkah berikutnya':`${C.fmt(e.from,0)} → ${e.to} kg`}</h2><p class="small muted spacer-top">${j.finished?'Pencatatan tetap tersedia untuk melanjutkan kebiasaan.':j.awaitingChoice?'65 kg sudah tercapai. Kamu yang memutuskan apakah ingin melanjutkan.':`Fokus pada satu fase. Estimasi durasi ${C.duration(e.from-e.to)} sejak fase dimulai.`}</p>${bar(j.progress)}<div class="between small"><strong>${C.pct(j.progress)} ${j.progress!==null?'fase ini':''}</strong><span>${j.remaining!==null?`${C.fmt(j.remaining)} kg lagi`:'Menunggu catatan timbang'}</span></div>${j.progress===1&&e?'<p class="small spacer-top">Menunggu akhir minggu untuk pengesahan.</p>':''}<div style="margin-top:25px">${btn(`Lihat roadmap ${icon('arrow')}`,'roadmap','')}</div></section>`;}
function habitTiles(w){return [['Nutrisi','leaf',w.green+w.yellow,w.coverage.nutrition,'hari memenuhi minimum'],['Protein','protein',w.protein,w.coverage.proteinG,'hari mencapai target'],['Gerak','walk',w.movement,w.coverage.movement,'hari mencapai target'],['Latihan','strength',w.strength,w.strengthTarget,'sesi minggu ini']].map(([label,ic,n,d,desc])=>`<div class="habit-tile"><div class="habit-title">${icon(ic)}${label}</div><div class="habit-number">${n} <span>/ ${d} ${label==='Latihan'?'sesi':'tercatat'}</span></div>${bar(d?n/d:null)}<small class="muted">${desc}</small></div>`).join('');}
function dashboard(){const d=today(),j=C.journey(state,d),w=C.weeklySummary(state,C.weekStart(d),d),t=C.trend(state,w.start,d);return pageHead('Langkah kecil, progres nyata.','Fokus ke kebiasaan hari ini. Progres akan mengikuti.',btn(`${icon(state.entries[d]?'edit':'plus')} ${state.entries[d]?'Edit catatan hari ini':'Catat hari ini'}`,'today','primary'))+`<div class="grid asym">${weightCard(j.source)}${focusCard(j)}</div><div class="grid section-gap"><section class="card"><div class="card-head"><h2>Target berikutnya</h2>${badge(j.next?'Target saat ini':j.finished?'Tercapai':'Evaluasi',j.next?'green':'')}</div><div class="target-row"><span class="target-symbol">${icon('target')}</span><div><strong>${j.next?`${j.next} kg`:j.finished?'Target tercapai':'Evaluasi di 65 kg'}</strong><p class="muted small">${j.next?`Disahkan saat rata-rata minggu selesai ≤ ${j.next} kg.`:'Buka Roadmap untuk melihat perjalananmu.'}</p></div></div>${j.next&&j.average!==null?`<p class="small muted spacer-top">Sisa ${C.fmt(Math.max(0,j.average-j.next))} kg berdasarkan ${C.period(j.source.start)}.</p>`:''}</section><section class="card soft"><div class="card-head"><h2>Hari yang cukup baik</h2>${icon('leaf')}</div><p class="muted small">Tidak harus semua target tercapai. Nutrisi sesuai minimum, protein cukup, gerak, atau latihan: satu saja sudah berarti.</p><div class="between spacer-top"><strong>${w.mvd} dari ${w.eligible.length} hari memenuhi minimum</strong>${btn('Lihat MVD','weekly','ghost')}</div><p class="small muted">${w.unknown} hari belum diketahui · ${C.period(w.start)}</p></section></div><section class="card section-gap"><div class="card-head"><div><h2>Kebiasaan minggu ini</h2><p class="muted small" style="margin-top:6px">${C.period(w.start)}</p></div>${btn(`Lihat review ${icon('arrow')}`,'weekly','ghost')}</div><div class="between wrap" style="margin-bottom:24px"><div>${badge(w.status,w.score>=.6?'green':'',w.score>=.6?'check':'info')} ${w.score!==null?badge(`${C.pct(w.score)}${w.temporary?' · Sementara':''}`):''}</div><span class="muted small">${w.ongoing?'Minggu berjalan':'Minggu selesai'}</span></div><div class="habit-grid">${habitTiles(w)}</div><hr class="divider"><div class="between wrap"><div class="habit-title" style="margin:0">${icon('chart')} Tren berat</div>${badge(t.label)}</div><p class="small muted spacer-top">${t.pace===null?'Interpretasi tersedia setelah 3 minggu selesai berurutan dengan data cukup.':`${C.period(t.start)} hingga ${C.formatDate(t.end)} · ${C.fmt(t.pace)} kg/minggu`}</p></section><div class="between wrap section-gap small muted"><span>Rencana jangka panjang: ${state.profile.longTermGoalKg} kg · evaluasi di 65 kg</span><span>Progress keseluruhan ${C.pct(j.overall)}</span></div>`;}
function chart(w,compact=false){const pts=w.weights, values=pts.map(e=>e.weightKg);if(!pts.length)return `<div class="empty-box">${icon('chart')}<br>Belum ada catatan timbang dalam periode ini.</div>`;let min=Math.floor((Math.min(...values)-.2)*2)/2,max=Math.ceil((Math.max(...values)+.2)*2)/2;if(min===max)max=min+1;const width=440,height=compact?170:215,left=44,right=22,top=28,bottom=34;const x=i=>left+i*(width-left-right)/6,y=v=>top+(max-v)/(max-min)*(height-top-bottom);return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Berat harian dalam kg, ${C.period(w.start)}">${[0,1,2].map(i=>{const v=min+(max-min)*i/2;return `<line x1="${left}" x2="${width-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e3ebe6" stroke-dasharray="3 4"/><text x="${left-9}" y="${y(v)+4}" text-anchor="end">${C.fmt(v)}</text>`;}).join('')}${w.dates.map((date,i)=>`<text x="${x(i)}" y="${height-7}" text-anchor="middle">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'][i]}</text>`).join('')}${pts.map(e=>{const i=w.dates.indexOf(e.localDate);return `<circle cx="${x(i)}" cy="${y(e.weightKg)}" r="5" fill="#187563"/><text class="weight-label" x="${x(i)}" y="${y(e.weightKg)-12}" text-anchor="middle">${C.fmt(e.weightKg)}</text>`;}).join('')}</svg>${!compact?`<p class="small muted">${w.eligible.filter(d=>!state.entries[d]?.weightKg).map(d=>C.formatDate(d,{weekday:'short'})).join(', ')||'Semua hari yang berlangsung sudah ditimbang'}${w.eligible.some(d=>!state.entries[d]?.weightKg)?': tidak ditimbang.':''} Titik menunjukkan catatan asli, tanpa interpolasi.</p>`:''}`;}
function rawEntry(date){const e=state.entries[date]||C.blankEntry(date);return Object.fromEntries(Object.entries(e).filter(([k])=>!['createdAt','updatedAt'].includes(k)).map(([k,v])=>[k,v===null?'':typeof v==='number'?String(v).replace('.',','):String(v)]));}
function initDaily(date){selectedDate=date;dailyDraft=rawEntry(date);savedDraft=JSON.stringify(dailyDraft);expandedHelp.clear();}
function readDaily(){const f=document.querySelector('#daily-form');if(f)dailyDraft=Object.fromEntries(new FormData(f));return dailyDraft;}
function help(name,text){return `<button type="button" class="info-button" data-act="help" data-help="${name}" aria-label="Penjelasan target ${{nutrition:'nutrisi',proteinG:'protein',movement:'gerak',strength:'latihan kekuatan'}[name]||name}" aria-controls="help-${name}" aria-expanded="${expandedHelp.has(name)}">${icon('info')}</button><span hidden id="help-copy-${name}">${esc(text)}</span>`;}
function choiceField(label,name,options,helpText,hint=''){return `<div class="field"><div class="field-label" id="${name}-label">${label}${helpText?help(name,helpText):''}</div><input type="hidden" name="${name}" value="${esc(dailyDraft[name])}"><div class="choices ${options.length===3?'three':''}" role="group" aria-labelledby="${name}-label">${options.map(([v,l,s,color])=>`<button type="button" class="choice ${color||''}" data-act="choice" data-field="${name}" data-value="${v}" aria-pressed="${dailyDraft[name]===v}"><strong>${color?`<i class="dot ${color}"></i>`:''}${l}</strong>${s?`<small>${s}</small>`:''}</button>`).join('')}</div>${hint?`<p>${hint}</p>`:''}<p class="error" id="${name}-error"></p>${helpText?`<div class="help" id="help-${name}" ${expandedHelp.has(name)?'':'hidden'}>${helpText}</div>`:''}</div>`;}
function mvdPreview(){const target=C.targetAt(state,selectedDate);const parsed=C.validateEntry(dailyDraft,state.profile,today()).entry,m=C.mvd(parsed,target);return `<div class="mvd-icon">${icon(m.state==='achieved'?'check':'leaf')}</div><span class="eyebrow muted">Ringkasan isian · preview</span><h2 class="summary-title spacer-top">${m.state==='achieved'?`MVD tercapai · ${m.actions.length} tindakan tercapai`:m.state==='not_achieved'?'Belum ada target tindakan tercapai':'Belum dapat ditentukan'}</h2>${m.actions.length?`<ul class="action-list">${m.actions.map(a=>`<li>${icon('check')}${a}</li>`).join('')}</ul>`:'<p class="small muted spacer-top">Isi yang tersedia. Satu tindakan tercapai sudah memenuhi minimum hari ini.</p>'}<hr class="divider"><p class="small muted">MVD = minimal satu target tindakan tercapai. Berat badan dan catatan bebas tidak dihitung sebagai tindakan.</p>`;}
function daily(){const target=C.targetAt(state,selectedDate),existing=!!state.entries[selectedDate];return pageHead('Catatan Harian','Isi yang tersedia. Catatan boleh belum lengkap.',`<span class="save-state" id="save-state">${icon(existing?'check':'edit')}${existing?'Tersimpan':'Belum disimpan'}</span>`)+`<div class="daily-layout"><div><div class="date-switch"><button class="icon-btn" aria-label="Hari sebelumnya" data-act="day-prev" ${selectedDate<=state.profile.startDate?'disabled':''}>${icon('left')}</button><div class="date-center"><input class="input" type="date" id="day-picker" value="${selectedDate}" min="${state.profile.startDate}" max="${today()}" aria-label="Tanggal catatan"><small class="muted">${C.formatDate(selectedDate,{weekday:'long'})}</small></div><button class="icon-btn" aria-label="Hari berikutnya" data-act="day-next" ${selectedDate>=today()?'disabled':''}>${icon('right')}</button></div><form id="daily-form" class="card form-card" novalidate><input name="localDate" type="hidden" value="${selectedDate}"><div id="form-error" class="error-banner" role="alert"></div>${inputField('Berat badan','weightKg',dailyDraft.weightKg,{unit:'kg',optional:true,help:'Tidak harus menimbang setiap hari.'})}${choiceField('Nutrisi','nutrition',[['green','Hijau','Sesuai rencana','green'],['yellow','Kuning','Sebagian besar sesuai','yellow'],['red','Merah','Jauh dari rencana','red']],'','Ketuk pilihan aktif sekali lagi untuk mengosongkan.')}<div class="field"><div class="field-label"><label for="proteinG">Protein</label>${help('proteinG',`Target kamu: ${target.proteinG} g/hari. Jumlah total protein yang kamu catat hari ini, bukan berat makanan. Mencapai target memenuhi satu tindakan MVD.`)}</div><div class="input-wrap"><input class="input" id="proteinG" name="proteinG" inputmode="decimal" value="${esc(dailyDraft.proteinG)}" aria-describedby="proteinG-error"><span class="unit">g</span></div><p id="proteinG-error" class="error"></p><div class="help" id="help-proteinG" ${expandedHelp.has('proteinG')?'':'hidden'}>Target kamu: ${target.proteinG} g/hari. Jumlah total protein, bukan berat makanan.</div></div>${choiceField('Gerak','movement',[['achieved','Tercapai'],['not_yet','Belum']],`Target kamu: total ${target.movementMinutes} menit berjalan hari ini. Boleh dicicil. Aktivitas lain boleh dicatat berdasarkan penilaian kamu, tanpa konversi intensitas otomatis.`)}${choiceField('Latihan kekuatan','strength',[['done','Selesai'],['not_today','Tidak hari ini']],`Target: ${target.strengthSessions} sesi/minggu. Maksimal satu sesi per hari. Istirahat tetap netral dan bukan missed workout.`)}<div class="field"><label for="note">Catatan <span class="optional">Opsional</span></label><textarea id="note" name="note" rows="3" maxlength="500" placeholder="Apa yang memengaruhi harimu?" aria-describedby="note-error">${esc(dailyDraft.note)}</textarea><div class="between"><p>Tulis hal kecil yang ingin kamu ingat.</p><span class="small muted" id="note-count">${dailyDraft.note.length}/500</span></div><p class="error" id="note-error"></p></div><div class="mvd-mobile" id="mvd-mobile">${mvdPreview()}</div><div class="save-actions"><button class="btn primary" type="submit">${icon('check')} Simpan catatan</button>${existing?btn(icon('trash'),'delete-day','danger','aria-label="Hapus catatan tanggal ini"'):''}</div>${existing?btn('Pindahkan ke tanggal lain','move-day','ghost wide spacer-top'):''}</form></div><aside class="daily-side stack"><section class="card soft" id="mvd-preview">${mvdPreview()}</section><div class="note-box">${icon('shield')}<span>Ringkasan ini mengikuti isianmu. Data di halaman lain berubah setelah kamu menyimpan.</span></div></aside></div>`;}
function weekly(){const w=C.weeklySummary(state,selectedWeek,today()),t=C.trend(state,selectedWeek,today());const target=C.targetAt(state,w.eligible[0]||w.start);return pageHead('Review Mingguan','')+`<div class="date-switch"><button class="icon-btn" data-act="week-prev" aria-label="Minggu sebelumnya" ${selectedWeek<=C.weekStart(state.profile.startDate)?'disabled':''}>${icon('left')}</button><div class="date-center"><strong>${C.period(selectedWeek)}</strong></div><button class="icon-btn" data-act="week-next" aria-label="Minggu berikutnya" ${selectedWeek>=C.weekStart(today())?'disabled':''}>${icon('right')}</button></div><section class="card soft"><div class="card-head"><h2>Minimum Viable Day</h2>${icon('leaf')}</div><div class="metric medium">${w.mvd}/${w.eligible.length} <span>hari</span></div><p class="small">Minimal satu tindakan tercapai per hari.</p><div class="day-dots">${w.days.map((d,i)=>`<div class="day-dot"><span class="${!d.eligible?'future':d.state==='achieved'?'yes':d.state==='not_achieved'?'no':''}" aria-label="${C.formatDate(d.date)}: ${!d.eligible?'di luar periode':d.state==='achieved'?'tercapai':d.state==='not_achieved'?'belum tercapai':'belum diketahui'}">${!d.eligible?'·':d.state==='achieved'?icon('check'):d.state==='not_achieved'?'−':'?'}</span>${['Sen','Sel','Rab','Kam','Jum','Sab','Min'][i]}<small>${Number(d.date.slice(8,10))}</small></div>`).join('')}</div></section><div class="grid asym section-gap"><section class="card"><h2>Berat minggu ini <span class="muted small">kg</span></h2>${chart(w)}</section><section class="card"><div class="card-head"><h2>Tren berat</h2>${icon('chart')}</div>${badge(t.label,t.label==='Sesuai rentang rencana'?'green':'')}<p class="small muted spacer-top">${t.pace===null?'Interpretasi membutuhkan 3 minggu selesai berurutan dengan minimal 3 catatan per minggu.':`${C.fmt(t.pace)} kg/minggu · dibandingkan rencana 0,4–0,6 kg/minggu.`}</p><details class="spacer-top"><summary class="small text-link">Lihat periode perhitungan</summary><div class="history-list">${t.rows.map(x=>`<div class="history-item"><span>${C.period(x.start)}</span><strong>${C.fmt(x.average)} kg<br><span class="muted">${x.weights.length} catatan</span></strong></div>`).join('')}</div></details><p class="small muted spacer-top">Tren dan konsistensi adalah dua indikator terpisah. Label tren membandingkan data dengan rencana, bukan penilaian kesehatan.</p></section></div><div class="grid asym section-gap"><section class="card"><div class="card-head"><h2>Rata-rata mingguan</h2>${badge(w.ongoing?'Sementara':'Minggu selesai')}</div><div class="metric ${w.average===null?'empty':''}">${w.average===null?'Belum cukup data':`${C.fmt(w.average)} <span>kg</span>`}</div><p class="small muted">Berdasarkan ${w.weights.length} catatan timbang${w.weights.length<3?' · minimal 3 catatan':''}</p><p class="small spacer-top">${w.delta!==null?`${w.delta>0?'+':''}${C.fmt(w.delta)} kg vs minggu sebelumnya${w.ongoing?' · Perbandingan sementara':''}`:w.firstWeek?'Minggu pertama: belum ada pembanding.':'Tidak tersedia: data minggu ini atau tepat sebelumnya belum cukup.'}</p></section><section class="card"><div class="card-head"><h2>Konsistensi</h2>${badge(w.status,w.score>=.6?'green':'')}</div><div class="metric ${w.score===null?'empty':''}">${w.score===null?'Belum cukup data':C.pct(w.score)}</div><p class="small muted">${w.score===null?'Perlu jawaban di minimal 5 hari untuk setiap kebiasaan.':`${w.temporary?'Sementara · ':''}Rata-rata empat kebiasaan, bobot sama.`}</p>${w.status==='Perlu check-in'?'<div class="note-box spacer-top">Dua minggu lengkap terasa berat. Apa hambatan yang bisa kita tinjau?</div>':''}</section></div><section class="card section-gap"><div class="card-head"><h2>Kebiasaan minggu ini</h2>${badge(w.temporary?'Coverage parsial':'Data lengkap')}</div>${[['Nutrisi',`${w.green} hijau · ${w.yellow} kuning · ${w.red} merah`,`${w.green+w.yellow} hari memenuhi minimum · ${w.coverage.nutrition} hari tercatat`,w.components.nutrition],['Protein',`${w.protein} hari mencapai target · ${w.coverage.proteinG} hari tercatat`,'Menggunakan target yang berlaku pada setiap tanggal.',w.components.proteinG],['Gerak',`${w.movement} hari mencapai target · ${w.coverage.movement} hari tercatat`,'Durasi minimum mengikuti target pada setiap tanggal.',w.components.movement],['Latihan kekuatan',`${w.strength}/${w.strengthTarget} sesi`,`${w.coverage.strength} hari terjawab · istirahat netral`,w.components.strength]].map(([l,n,d,s])=>`<div class="review-habit"><div class="between"><h3>${l}</h3><strong class="small">${s===null?'Belum tercatat':C.pct(s)}</strong></div><p class="small spacer-top">${n}</p>${bar(s)}<p class="small muted">${d}</p></div>`).join('')}<div class="note-box spacer-top">${icon('info')}<span>Nutrisi: hijau 1, kuning 0,5, merah 0. Hari kosong tidak dihitung sebagai gagal. Setiap kebiasaan perlu jawaban di minimal 5 hari agar skor gabungan tampil.</span></div><details class="spacer-top"><summary class="small text-link">Lihat coverage dan target harian</summary><div class="history-list">${w.eligible.map(d=>{const e=state.entries[d],v=C.targetAt(state,d);return `<div class="history-item"><span>${C.formatDate(d,{weekday:'short',day:'numeric'})}<br>${C.FIELDS.filter(k=>e?.[k]!=null).length}/4 kebiasaan terisi</span><span>${v.proteinG} g protein · ${v.movementMinutes} menit gerak</span></div>`;}).join('')}</div></details></section><form id="reflection-form" class="card section-gap"><div class="card-head"><h2>Refleksi</h2><span class="optional">Opsional</span></div><div class="field"><label for="reflection">Apa yang membuat minggu ini sulit?</label><textarea id="reflection" name="reflection" rows="4" maxlength="2000" placeholder="Misalnya, jadwal berubah atau makan di luar…">${esc(reflectionDraft)}</textarea></div><div id="reflection-error" class="error-banner" role="alert"></div><button type="submit" class="btn primary wide">Simpan refleksi</button><p class="form-status" id="reflection-status">${reflectionSaved?'Tersimpan':''}</p></form>`;}
function roadmap(){const j=C.journey(state,today());return pageHead('Roadmap','')+`<section class="card between roadmap-stats"><div><span class="small muted">Berat awal</span><div class="metric medium">${C.fmt(state.profile.baselineKg)} <span>kg</span></div></div><div style="text-align:right"><span class="small muted">Rata-rata mingguan</span><div class="metric medium">${C.fmt(j.average)} <span>kg</span></div>${j.source?`<span class="small muted">${C.period(j.source.start)} · ${j.source.weights.length} catatan</span>`:''}</div></section>${j.awaitingChoice?`<section class="card soft section-gap"><h2>65 kg tercapai. Pilih langkah berikutnya.</h2><p class="small muted spacer-top">Evaluasi juga bagaimana tubuh terasa dan progres di luar timbangan. Fase berikutnya tidak aktif otomatis.</p><div class="save-actions">${btn('Cukup di 65 kg','finish-65')}${btn('Lanjut menuju 60 kg','continue-60','primary')}</div></section>`:''}${j.finished?`<div class="note-box section-gap">${icon('check')}<span><strong>Target tercapai.</strong> Kamu tetap bisa mencatat kebiasaan tanpa target penurunan baru.</span></div>`:''}<div class="epic-list section-gap">${j.epics.map(e=>{const active=e.status==='active',completed=e.status==='completed',labels={active:'Fokus saat ini',completed:'Selesai',locked:'Terkunci',optional:'Opsional',not_selected:'Tidak dipilih'};const info=e.n===1?'Bangun ritme kebiasaan yang bisa kamu jalani.':e.n===2?`Terbuka setelah rata-rata minggu selesai ≤ 75 kg. Saat mencapai 70 kg, penurunan sejak berat awal adalah ${C.fmt(state.profile.baselineKg-70)} kg.`:e.n===3?'Terbuka setelah rata-rata minggu selesai ≤ 70 kg. Evaluasi progres di luar angka timbangan.':'Aktif setelah 65 kg sah tercapai dan kamu memilih lanjut. Tidak aktif secara otomatis.';return `<details class="card epic-card ${active?'current':completed?'completed':e.n===4?'optional-phase':''}" ${active?'open':''}><summary>${icon('chevron','chevron')}${badge(labels[e.status],active||completed?'green':'',completed?'check':e.status==='locked'?'lock':active?'flag':'') }<div class="epic-title">Epic ${e.n}: ${C.fmt(e.from,0)} → ${e.to} kg</div><p class="small muted spacer-top">${info}</p></summary><div class="epic-content">${active?`${bar(j.progress)}<div class="between small"><strong>${C.pct(j.progress)} progres fase</strong><span>${j.remaining!==null?`${C.fmt(j.remaining)} kg lagi`:'Belum cukup data'}</span></div>${j.progress===1?'<p class="small spacer-top">Menunggu akhir minggu untuk pengesahan.</p>':''}`:''}<p class="small muted spacer-top">Estimasi durasi fase: ${C.duration(e.from-e.to)} sejak fase dimulai. Perkiraan, bukan tenggat.</p>${active&&j.remaining!==null?`<p class="small muted">Estimasi sisa fase: ${C.duration(j.remaining)} pada pace rencana 0,4–0,6 kg/minggu.</p>`:''}<div class="milestones">${e.targets.map(kg=>{const done=!!j.achieved[kg]&&(e.n!==4||!['optional','not_selected','locked'].includes(e.status)),isNext=kg===j.next;return `<div class="milestone ${done?'done':isNext?'active':''}">${icon(done?'check':isNext?'target':'lock')}<strong>${kg} kg</strong>${done?'Tercapai':isNext?'Target saat ini':'Terkunci'}${done?`<br><button class="btn ghost" data-act="achievement" data-kg="${kg}" style="font-size:11px">${C.formatDate(j.achieved[kg].firstReachedAt,{day:'numeric',month:'short'})}</button>`:''}</div>`;}).join('')}</div>${active&&j.next!==null&&j.average!==null?`<p class="small muted">Sisa ${C.fmt(Math.max(0,j.average-j.next))} kg menuju ${j.next} kg.</p>`:''}${completed?`<p class="small muted">Disahkan ${C.formatDate(j.achieved[e.to].firstReachedAt)} dari ${C.period(j.achieved[e.to].sourceWeek)}. Status tidak ditarik karena fluktuasi berikutnya.</p>`:''}</div></details>`;}).join('')}</div><section class="card section-gap"><div class="between"><h2>Rencana jangka panjang: ${state.profile.longTermGoalKg} kg</h2><strong>${C.pct(j.overall)}</strong></div>${bar(j.overall)}<p class="small muted">Evaluasi ulang di 65 kg, termasuk progres di luar timbangan.</p></section><section class="note-box section-gap">${icon('info')}<div><strong>Cara status berubah</strong><p>Milestone disahkan dari minggu Senin–Minggu yang sudah selesai, dengan minimal 3 catatan timbang. Dashboard dan Roadmap memakai sumber yang sama. Gembok berarti urutan fase, bukan pembatasan akses. Koreksi atau penghapusan data dapat mengubah pencapaian sebelumnya.</p></div></section>`;}
function settings(){const p=state.profile,t=C.targetAt(state,C.addDays(today(),1)),s=C.targetAt(state,C.addDays(C.weekStart(today()),7));return pageHead('Pengaturan','Target pribadi, riwayat perubahan, dan data kamu.',btn(`${icon('left')} Dashboard`,'dashboard'))+`<div class="settings-grid"><form id="settings-form" class="card" novalidate><h2>Profil & target pribadi</h2><div id="form-error" class="error-banner spacer-top" role="alert"></div><input type="hidden" name="startDate" value="${p.startDate}"><div class="form-grid spacer-top">${inputField('Berat awal','baselineKg',p.baselineKg,{unit:'kg',help:'Minimal 40 kg.'})}${inputField('Tinggi','heightCm',p.heightCm,{unit:'cm'})}</div><div class="field"><label for="longTermGoalKg">Target jangka panjang</label><select id="longTermGoalKg" name="longTermGoalKg"><option value="60" ${p.longTermGoalKg===60?'selected':''}>60 kg · evaluasi ulang di 65 kg</option><option value="65" ${p.longTermGoalKg===65?'selected':''}>65 kg · selesai di Epic 3</option></select></div><hr class="divider"><div class="form-grid">${inputField('Protein / hari','proteinG',t.proteinG,{unit:'g'})}${inputField('Gerak / hari','movementMinutes',t.movementMinutes,{unit:'mnt'})}</div><p class="small muted" style="margin-bottom:20px">Perubahan protein dan gerak berlaku mulai ${C.formatDate(C.addDays(today(),1))}.</p>${inputField('Latihan kekuatan / minggu','strengthSessions',s.strengthSessions,{unit:'sesi',help:`Perubahan berlaku Senin, ${C.formatDate(C.addDays(C.weekStart(today()),7))}.`})}<div class="note-box">${icon('clock')}<span>Catatan lama tetap memakai target pada tanggalnya. Target ini pengaturan pencatatan pribadi, bukan rekomendasi medis otomatis.</span></div><button class="btn primary wide spacer-top" type="submit">Simpan pengaturan</button></form><div class="stack"><section class="card"><div class="card-head"><h2>Data perjalanan</h2>${icon('shield')}</div><p class="small muted">Catatan tersimpan di akun. Login dengan akun yang sama untuk mengaksesnya dari perangkat lain.</p><hr class="divider"><div class="between small"><span>Mulai</span><strong>${C.formatDate(p.startDate)}</strong></div><div class="between small spacer-top"><span>Zona waktu perjalanan</span><strong>${esc(p.timeZone)}</strong></div><p class="small muted spacer-top">Minggu: Senin–Minggu. Tanggal historis mengikuti zona waktu perjalanan.</p><hr class="divider">${btn(`${icon('download')} Ekspor seluruh data CSV`,'export','wide')}<p class="small muted spacer-top">Termasuk profil, catatan, target bertanggal, refleksi, dan keputusan fase. CSV dapat dibaca di luar aplikasi; belum bisa diimpor kembali.</p><p class="small muted spacer-top">Ekspor terakhir: ${state.meta.lastExportAt?esc(new Date(state.meta.lastExportAt).toLocaleString('id-ID')):'Belum pernah'}</p></section><section class="card"><h2>Riwayat target</h2><div class="history-list">${state.targets.map(v=>`<div class="history-item"><span>${C.formatDate(v.effectiveDate)}${v.effectiveDate>today()?'<br>Terjadwal':''}</span><span>${[v.proteinG!=null?`${v.proteinG} g protein`:null,v.movementMinutes!=null?`${v.movementMinutes} menit gerak`:null,v.strengthSessions!=null?`${v.strengthSessions} sesi latihan`:null].filter(Boolean).join('<br>')}</span></div>`).join('')}</div></section><section class="card"><h2>Hapus data</h2><p class="small muted spacer-top">Menghapus seluruh perjalanan dari akun di semua perangkat, termasuk profil dan catatan. Tidak bisa diurungkan.</p>${btn(`${icon('trash')} Hapus semua data`,'clear-all','danger wide spacer-top')}</section></div></div>`;}

function upcoming(){return `<section class="card"><span class="eyebrow muted">Perjalanan dijadwalkan</span><h1 class="spacer-top">Mulai besok, ${C.formatDate(state.profile.startDate,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h1><p class="muted spacer-top">Targetmu sudah tersimpan. Catatan harian dan review baru tersedia pada tanggal mulai, sesuai zona waktu saat kamu mendaftar. Kembali besok atau muat ulang halaman.</p><div class="spacer-top">${btn('Lihat pengaturan','settings','ghost')}</div></section>`;}
function applyFriendlyLabels(){document.querySelector('[data-act="settings"]')?.setAttribute('aria-label','Profil');const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);for(let node;node=walker.nextNode();)node.nodeValue=node.nodeValue.replace('Pengaturan awal · hanya sekali','Profil awal · hanya sekali').replace('Pengaturan awal','Profil awal').replace('Simpan pengaturan','Simpan profil').replace('halaman Pengaturan','halaman Profil').replace(/^Pengaturan$/,'Profil');}
function render(){document.title=`${state?.profile?(tabs.find(t=>t[0]===route)?.[1]||'Profil'):'Mulai perjalanan'} · Epic`;const pending=state?.profile&&state.profile.startDate>today()&&route!=='settings';app.innerHTML=state?.profile?shell(pending?upcoming():({dashboard,daily,weekly,roadmap,settings}[route]||dashboard)()):onboarding();applyFriendlyLabels();renderAccount();if(route==='daily'&&state?.profile&&!pending)updateDailyPreview();if(route==='settings')profileSaved=formSignature('#settings-form');}
function formSignature(selector){const form=document.querySelector(selector);return form?JSON.stringify(Object.fromEntries(new FormData(form))):'';}
function dirty(){if(!state?.profile)return false;if(route==='daily'){readDaily();return JSON.stringify(dailyDraft)!==savedDraft;}if(route==='weekly')return (document.querySelector('#reflection')?.value??reflectionDraft)!==reflectionSaved;if(route==='settings')return formSignature('#settings-form')!==profileSaved;return false;}
function setErrors(errors,prefix=''){document.querySelectorAll('.error').forEach(el=>el.textContent='');document.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));for(const[k,v]of Object.entries(errors)){const el=document.getElementById(`${prefix}${k}-error`)||document.getElementById('form-error');if(el)el.textContent=v;document.getElementById(k)?.setAttribute('aria-invalid','true');}const invalid=document.querySelector('[aria-invalid=true]');invalid?.focus();}
function showError(e,selector='#form-error'){const el=document.querySelector(selector);if(el)el.textContent=e.message||String(e);else toast(e.message||String(e));}
function toast(message,action=null){clearTimeout(toastTimer);const root=document.querySelector('#toast');root.innerHTML=`<div class="toast-inner"><span>${esc(message)}</span>${action?`<button type="button" data-act="${action.id}">${esc(action.label)}</button>`:''}</div>`;toastTimer=setTimeout(()=>root.innerHTML='',action?10000:6500);}
async function dialog(title,copy,actions,extra=''){const root=document.querySelector('#modal-root');const before=document.activeElement;return new Promise(resolve=>{root.innerHTML=`<dialog class="modal" aria-labelledby="modal-title"><h2 id="modal-title">${title}</h2><p>${copy}</p>${extra}<div class="modal-actions">${actions.map(a=>`<button type="button" class="btn ${a.kind||''}" data-result="${a.id}">${a.label}</button>`).join('')}</div></dialog>`;const d=root.firstElementChild;function finish(result){const value=d.querySelector('input')?.value;d.close();root.innerHTML='';before?.focus();resolve({id:result,value});}d.addEventListener('click',e=>{const b=e.target.closest('[data-result]');if(b)finish(b.dataset.result);});d.addEventListener('cancel',e=>{e.preventDefault();finish('cancel');});d.showModal();});}
async function persist(next){busy=true;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{state=await DB.save(next);return true;}finally{busy=false;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}}
async function saveDaily(){if(busy)return false;readDaily();const {entry,errors}=C.validateEntry(dailyDraft,state.profile,today());setErrors(errors);if(Object.keys(errors).length)return false;try{const existed=!!state.entries[selectedDate];const before=C.signature(C.achievements(state,today()));const next=structuredClone(state);const now=new Date().toISOString();next.entries[selectedDate]={...entry,createdAt:state.entries[selectedDate]?.createdAt||now,updatedAt:now};const after=C.signature(C.achievements(next,today()));next.meta.seenAchievementSignature=after;await persist(next);initDaily(selectedDate);render();toast(before!==after?(existed?'Catatan tersimpan. Koreksi data mengubah riwayat pencapaian di Dashboard dan Roadmap.':'Catatan tersimpan. Milestone baru disahkan di Dashboard dan Roadmap.'):'Catatan tersimpan. Semua ringkasan sudah diperbarui.');return true;}catch(e){showError(e);return false;}}
async function saveReflection(){if(busy)return false;reflectionDraft=document.querySelector('#reflection')?.value??reflectionDraft;try{const next=structuredClone(state);next.reflections[selectedWeek]={text:reflectionDraft,updatedAt:new Date().toISOString()};await persist(next);reflectionSaved=reflectionDraft;document.querySelector('#reflection-status').textContent='Tersimpan';toast('Refleksi tersimpan. Metrik tetap mengikuti catatan harian.');return true;}catch(e){showError(e,'#reflection-error');return false;}}
async function saveSettings(){if(busy)return false;const raw=Object.fromEntries(new FormData(document.querySelector('#settings-form')));const errors=C.validateProfile(raw,today());setErrors(errors);if(Object.keys(errors).length)return false;try{const before=C.signature(C.achievements(state,today()));let next=C.scheduleTargets(state,raw,today());next.profile={...state.profile,baselineKg:Math.round(raw.baselineKg*10)/10,heightCm:raw.heightCm,longTermGoalKg:Number(raw.longTermGoalKg)};if(next.profile.longTermGoalKg===65)next.decision={decisionDate:today(),optionalPhaseChoice:'stop'};const after=C.signature(C.achievements(next,today()));next.meta.seenAchievementSignature=after;await persist(next);render();toast(before!==after?'Profil diperbarui. Koreksi mengubah riwayat pencapaian.':'Pengaturan tersimpan. Tanggal berlakunya terlihat di riwayat target.');return true;}catch(e){showError(e);return false;}}
async function guard(){if(!dirty())return true;const r=await dialog('Ada perubahan belum disimpan','Simpan dulu agar isianmu tidak hilang saat berpindah halaman.',[{id:'save',label:'Simpan lalu lanjut',kind:'primary'},{id:'discard',label:'Buang perubahan'},{id:'cancel',label:'Tetap di halaman'}]);if(r.id==='save')return route==='daily'?saveDaily():route==='weekly'?saveReflection():saveSettings();return r.id==='discard';}
async function navigate(next,params={}){if(busy)return;if(!await guard())return;if(!state.profile)return;route=next;const d=today();if(route==='daily')initDaily(params.date||d);if(route==='weekly'){selectedWeek=params.week||C.weekStart(d);reflectionDraft=state.reflections[selectedWeek]?.text||'';reflectionSaved=reflectionDraft;}history.pushState(null,'',`#${route}`);render();window.scrollTo(0,0);}
function updateDailyPreview(){if(!state.profile||route!=='daily')return;const n=document.querySelector('#mvd-preview');if(n)n.innerHTML=mvdPreview();const mobile=document.querySelector('#mvd-mobile');if(mobile)mobile.innerHTML=mvdPreview();const save=document.querySelector('#save-state');if(save)save.innerHTML=JSON.stringify(dailyDraft)===savedDraft&&state.entries[selectedDate]?`${icon('check')}Tersimpan`:`${icon('edit')}Belum disimpan`;const count=document.querySelector('#note-count');if(count)count.textContent=`${dailyDraft.note.length}/500`;}
async function deleteDay(){const response=await dialog('Hapus catatan tanggal ini?',`Catatan ${C.formatDate(selectedDate)} akan dihapus. Ringkasan dan pencapaian dihitung ulang. Kamu bisa mengurungkan selama 10 detik.`,[{id:'delete',label:'Hapus catatan',kind:'danger'},{id:'cancel',label:'Batal'}]);if(response.id!=='delete')return;try{const before=C.signature(C.achievements(state,today())),entry=structuredClone(state.entries[selectedDate]);const next=structuredClone(state);delete next.entries[selectedDate];const after=C.signature(C.achievements(next,today()));next.meta.seenAchievementSignature=after;await persist(next);undoEntry=entry;clearTimeout(undoTimer);undoTimer=setTimeout(()=>undoEntry=null,10000);initDaily(selectedDate);render();toast(before!==after?'Catatan dihapus. Pencapaian Dashboard dan Roadmap berubah.':'Catatan dihapus.',{id:'undo-day',label:'Urungkan'});}catch(e){showError(e);}}
async function undoDay(){if(!undoEntry)return;try{const next=structuredClone(state);if(next.entries[undoEntry.localDate]){toast('Tanggal itu sudah diisi lagi. Catatan baru tidak ditimpa.');return;}next.entries[undoEntry.localDate]=undoEntry;next.meta.seenAchievementSignature=C.signature(C.achievements(next,today()));await persist(next);undoEntry=null;clearTimeout(undoTimer);if(route==='daily')initDaily(selectedDate);render();toast('Catatan dipulihkan.');}catch(e){toast(e.message);}}
async function moveDay(){if(!await guard())return;const r=await dialog('Pindahkan tanggal catatan','Tanggal tujuan harus masih dalam perjalanan dan belum mempunyai catatan.',[{id:'move',label:'Pindahkan catatan',kind:'primary'},{id:'cancel',label:'Batal'}],`<div class="field"><label for="move-date">Tanggal tujuan</label><input id="move-date" type="date" class="input" min="${state.profile.startDate}" max="${today()}" value="${selectedDate}"></div>`);if(r.id!=='move')return;const date=r.value;if(!C.validDate(date)||date<state.profile.startDate||date>today()){toast('Pilih tanggal yang valid dalam perjalanan.');return;}if(date===selectedDate)return;if(state.entries[date]){const choice=await dialog('Tanggal tujuan sudah terisi','Catatan yang ada tidak akan ditimpa. Kamu bisa membuka dan mengedit tanggal tersebut.',[{id:'open',label:'Buka catatan tujuan',kind:'primary'},{id:'cancel',label:'Batal'}]);if(choice.id==='open')navigate('daily',{date});return;}try{const next=structuredClone(state);next.entries[date]={...next.entries[selectedDate],localDate:date,updatedAt:new Date().toISOString()};delete next.entries[selectedDate];const before=C.signature(C.achievements(state,today())),after=C.signature(C.achievements(next,today()));next.meta.seenAchievementSignature=after;await persist(next);initDaily(date);render();toast(before!==after?'Tanggal dipindahkan. Koreksi mengubah riwayat pencapaian.':'Tanggal catatan dipindahkan.');}catch(e){showError(e);}}
async function exportData(){if(!await guard())return;try{const blob=new Blob([C.exportCsv(state)],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`epic-diet-tracker-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);const next=structuredClone(state);next.meta.lastExportAt=new Date().toISOString();await persist(next);render();toast('CSV diekspor. File dapat dibaca, tetapi belum bisa diimpor kembali.');}catch(e){toast(e.message);}}
async function clearAll(){if(!await guard())return;let r=await dialog('Hapus seluruh perjalanan?','Profil, target, catatan, refleksi, dan keputusan fase akan dihapus dari akun di semua perangkat. Tidak bisa diurungkan. File CSV yang sudah diunduh tetap ada.',[{id:'export',label:'Ekspor CSV terlebih dahulu'},{id:'delete',label:'Hapus semua data',kind:'danger'},{id:'cancel',label:'Batal'}]);if(r.id==='export'){await exportData();return;}if(r.id!=='delete')return;try{state=await DB.clear(state.meta.revision);dailyDraft=null;savedDraft=null;reflectionDraft='';reflectionSaved='';profileSaved='';undoEntry=null;clearTimeout(undoTimer);expandedHelp.clear();route='dashboard';history.replaceState(null,'','#dashboard');render();toast('Semua data perjalanan dihapus dari akun.');}catch(e){toast(e.message);}}
async function choosePhase(choice){if(!C.achievements(state,today())[65])return;const r=await dialog(choice==='continue'?'Lanjut menuju 60 kg?':'Cukup di 65 kg?',choice==='continue'?'Epic 4 akan aktif dengan target berikutnya 62 kg. Kamu tetap bisa mengubah target di Pengaturan.':'Target jangka panjang berubah menjadi 65 kg. Pencatatan tetap tersedia untuk menjaga kebiasaan.',[{id:'yes',label:choice==='continue'?'Aktifkan Epic 4':'Pilih 65 kg',kind:'primary'},{id:'cancel',label:'Batal'}]);if(r.id!=='yes')return;const next=structuredClone(state);next.profile.longTermGoalKg=choice==='continue'?60:65;next.decision={decisionDate:today(),optionalPhaseChoice:choice};await persist(next);render();toast(choice==='continue'?'Epic 4 aktif. Dashboard dan Roadmap diperbarui.':'Target 65 kg dipilih. Perjalananmu tercapai.');}

document.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;try{if(event.target.id==='onboard-form'){const raw=Object.fromEntries(new FormData(event.target)),errors=C.validateProfile(raw,today());setErrors(errors);if(Object.keys(errors).length)return;const next=C.initialState();next.meta.revision=state.meta.revision||0;next.profile={startDate:raw.startDate,baselineKg:Math.round(raw.baselineKg*10)/10,heightCm:raw.heightCm,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,longTermGoalKg:Number(raw.longTermGoalKg)};next.targets=[{effectiveDate:raw.startDate,proteinG:raw.proteinG,movementMinutes:raw.movementMinutes,strengthSessions:raw.strengthSessions}];await persist(next);route='dashboard';lastDay=today();render();window.scrollTo(0,0);toast(raw.startDate>today()?'Perjalanan dijadwalkan mulai besok.':'Perjalanan siap. Mulai dengan catatan pertamamu.');}else if(event.target.id==='daily-form')await saveDaily();else if(event.target.id==='reflection-form')await saveReflection();else if(event.target.id==='settings-form')await saveSettings();}catch(e){showError(e);}});
document.addEventListener('input',event=>{if(event.target.id==='baselineKg'){const visual=document.querySelector('.journey-viz');if(visual)visual.outerHTML=journeyVisual(event.target.value);}if(event.target.closest('#daily-form')){readDaily();updateDailyPreview();}if(event.target.id==='reflection'){reflectionDraft=event.target.value;document.querySelector('#reflection-status').textContent=reflectionDraft===reflectionSaved?'Tersimpan':'Belum disimpan';}});
document.addEventListener('change',async event=>{if(event.target.id==='day-picker'){const date=event.target.value;if(!C.validDate(date)||date<state.profile.startDate||date>today()){event.target.value=selectedDate;toast('Tanggal di luar perjalanan.');return;}await navigate('daily',{date});const picker=document.querySelector('#day-picker');if(picker)picker.value=selectedDate;}});
document.addEventListener('click',async event=>{const link=event.target.closest('[data-route]');if(link){event.preventDefault();await navigate(link.dataset.route);return;}const b=event.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act;try{if(['dashboard','weekly','roadmap','settings'].includes(a)){await navigate(a);return;}if(a==='today'){await navigate('daily');return;}if(a==='day-prev'||a==='day-next'){await navigate('daily',{date:C.addDays(selectedDate,a==='day-prev'?-1:1)});return;}if(a==='week-prev'||a==='week-next'){await navigate('weekly',{week:C.addDays(selectedWeek,a==='week-prev'?-7:7)});return;}if(a==='help'){const name=b.dataset.help,el=document.getElementById(`help-${name}`);el.hidden=!el.hidden;b.setAttribute('aria-expanded',!el.hidden);if(el.hidden)expandedHelp.delete(name);else expandedHelp.add(name);return;}if(a==='choice'){readDaily();const f=b.dataset.field,v=b.dataset.value;dailyDraft[f]=dailyDraft[f]===v?'':v;const form=document.querySelector('#daily-form');form.elements[f].value=dailyDraft[f];form.querySelectorAll(`[data-field="${f}"]`).forEach(el=>el.setAttribute('aria-pressed',el.dataset.value===dailyDraft[f]));updateDailyPreview();return;}if(a==='delete-day')await deleteDay();if(a==='undo-day')await undoDay();if(a==='move-day')await moveDay();if(a==='export')await exportData();if(a==='clear-all')await clearAll();if(a==='continue-60')await choosePhase('continue');if(a==='finish-65')await choosePhase('stop');if(a==='achievement'){const item=C.achievements(state,today())[Number(b.dataset.kg)];if(item)await dialog(`${b.dataset.kg} kg tercapai`,`Disahkan ${C.formatDate(item.firstReachedAt)} berdasarkan rata-rata minggu ${C.period(item.sourceWeek)}.`,[{id:'close',label:'Tutup',kind:'primary'}]);}}catch(e){showError(e);}});
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});
window.addEventListener('popstate',async()=>{const desired=location.hash.slice(1)||'dashboard';history.replaceState(null,'',`#${route}`);await navigate(['dashboard','daily','weekly','roadmap','settings'].includes(desired)?desired:'dashboard');});

function renderAccount(){
  if(!account)return;
  const main=document.querySelector('#main');
  if(!state?.profile){const header=main.querySelector('.onboarding-header');if(header){const exit=document.createElement('button');exit.className='btn ghost';exit.type='button';exit.dataset.act='logout';exit.textContent='Keluar';header.after(exit);}}
  if(route==='settings'&&state?.profile){
    const card=document.createElement('section');card.className='card account-card';
    card.innerHTML='<div><h2>Akun pribadi</h2><p class="small muted" translate="no">'+esc(account.username)+'</p><p class="small muted">'+(account.storage==='local'?'Preview lokal: sinkronisasi internet belum aktif.':'Catatan tersimpan di akun dan tersedia di perangkat lain.')+'</p></div>'+btn('Muat ulang catatan','refresh','')+btn('Keluar','logout','');
    main.append(card);
  }
}
document.addEventListener('click',async event=>{
  const action=event.target.closest('[data-act]')?.dataset.act;
  if(!['logout','refresh'].includes(action))return;
  if(!await guard())return;
  try{if(action==='logout')await DB.logout();location.reload();}catch(e){toast(e.message);}
});
let refreshing=false;
document.addEventListener('visibilitychange',async()=>{
  if(document.visibilityState!=='visible'||!account||!state?.profile||busy||refreshing||dirty())return;
  refreshing=true;
  try{const fresh=await DB.load();if(!busy&&!dirty()&&(fresh.meta.revision||0)!==(state.meta.revision||0)){state=fresh;if(route==='daily')initDaily(selectedDate);if(route==='weekly'){reflectionDraft=state.reflections[selectedWeek]?.text||'';reflectionSaved=reflectionDraft;}render();toast('Catatan terbaru dari akun dimuat.');}}
  catch(e){toast(e.message);}finally{refreshing=false;}
});

async function evaluateAchievements(){if(!state?.profile)return;const sig=C.signature(C.achievements(state,today()));if(sig!==state.meta.seenAchievementSignature){const next=structuredClone(state);next.meta.seenAchievementSignature=sig;await persist(next);if(sig!=='[]')toast('Pencapaian minggu selesai diperbarui. Lihat hasilnya di Roadmap.');}}
document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'&&state?.profile&&lastDay!==today()&&!dirty()){lastDay=today();await evaluateAchievements();if(route==='daily')initDaily(today());if(route==='weekly'){selectedWeek=C.weekStart(today());reflectionDraft=state.reflections[selectedWeek]?.text||'';reflectionSaved=reflectionDraft;}render();}});
try{
try{account=await DB.session();}catch(e){if(e.status!==401)throw e;await askLogin();account=await DB.session();}
state=await DB.load();
if(!state.profile&&!(state.meta.revision>0)){
  const local=await DB.legacy();
  if(local?.profile){
    const migration=await dialog('Pindahkan catatan lama?','Ada catatan di browser ini. Salin ke akun pribadi agar tersedia di perangkat lain setelah server cloud terhubung. Salinan lama tetap ada di browser.',[{id:'import',label:'Salin ke akun',kind:'primary'},{id:'skip',label:'Nanti saja'}]);
    if(migration.id==='import'){const copy=structuredClone(local);copy.meta.revision=state.meta.revision||0;state=await DB.save(copy);}
  }
}
if(state.meta.schemaVersion!==1)throw new Error('Versi data tidak didukung. Data tidak diubah. Gunakan versi aplikasi yang sesuai.');if(state.profile){route=['dashboard','daily','weekly','roadmap','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard';initDaily(today());selectedWeek=C.weekStart(today());reflectionDraft=state.reflections[selectedWeek]?.text||'';reflectionSaved=reflectionDraft;lastDay=today();await evaluateAchievements();}render();}catch(e){loadError='Data akun belum bisa dibuka. Periksa koneksi lalu coba lagi. '+e.message;app.innerHTML=`<main id="main" class="onboarding"><header class="onboarding-header">${brand()}${switcher()}</header><section class="card spacer-top"><h1>Catatan belum bisa dibuka</h1><p class="spacer-top">${esc(loadError)}</p><a href="/" class="btn primary spacer-top">Coba lagi</a></section></main>`;}
// Optional browser-standard navigation tool: does not expose health records.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'navigate_epic_tracker',description:'Open a tracker page. Unsaved changes still require a choice in the visible interface.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['dashboard','daily','weekly','roadmap']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!tabs.some(t=>t[0]===input.page)||Object.keys(input).some(k=>k!=='page'))throw new Error('Invalid page');if(!state?.profile)throw new Error('Complete onboarding first');await navigate(input.page);return {page:route};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
